<?php foreach ($staff as $person): ?><tr><td><?= e($person['name']) ?></td><td><?= e($person['email']) ?></td><td><?= $person['role']==='admin'?'Quản trị viên':'Thủ thư' ?></td><td><?= $person['is_active']?'Đang hoạt động':'Đã khóa' ?></td><td><button class="button button-small button-outline" data-dialog-open="staff<?= (int)$person['id'] ?>">Sửa</button> <?php if ($person['role']==='librarian'): ?><a href="<?= e(url('/admin/permissions?user='.$person['id'])) ?>">Cấp quyền</a><?php endif; ?></td></tr><?php endforeach; ?>
